import{_ as a,o as e,c as i,ag as n}from"./chunks/framework.DHSXpJLs.js";const k=JSON.parse('{"title":"存储与前端对接","description":"","frontmatter":{},"headers":[],"relativePath":"development/integration.md","filePath":"development/integration.md","lastUpdated":1790779354000}'),t={name:"development/integration.md"};function p(o,s,l,d,h,r){return e(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="存储与前端对接" tabindex="-1">存储与前端对接 <a class="header-anchor" href="#存储与前端对接" aria-label="Permalink to &quot;存储与前端对接&quot;">​</a></h1><p>本文面向两类集成方：想把存储层接到自己数据库的，以及自研前端要接入的。协议细节（envelope、错误码、鉴权行为）以 <a href="/SourceAEC/reference/rest-api">REST API</a> 为准，本页讲存储契约与对接面。</p><h2 id="数据目录布局" tabindex="-1">数据目录布局 <a class="header-anchor" href="#数据目录布局" aria-label="Permalink to &quot;数据目录布局&quot;">​</a></h2><p>Go server 和两个 Python 服务必须共享同一个数据目录，配错会 404 或改错文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{VIEWER_DATA_DIR}/</span></span>
<span class="line"><span>├── uploads/{id}.ifc|.dxf              # 当前模型态（script/run 或 save 时原子替换）</span></span>
<span class="line"><span>├── staging/{modelId}.py                # agent 写脚本的中转落点，再由 API 暂存</span></span>
<span class="line"><span>├── projects/{projectID}/project.json   # 项目本体（原子 tmp + rename）</span></span>
<span class="line"><span>├── plans/{projectID}/                  # 方案产物版本目录（plan / bim_supplement / building）</span></span>
<span class="line"><span>├── skill-work/{projectID}/             # agent 文件工具的写白名单根；skill 中间产物，不版本化</span></span>
<span class="line"><span>└── models/{id}/</span></span>
<span class="line"><span>    ├── model.json                      # 模型状态：name/size/status/error（Go store，原子写）</span></span>
<span class="line"><span>    ├── model.xkt                       # converter 产物（静态直挂路径）</span></span>
<span class="line"><span>    ├── metadata.json                   # converter 产物（xeokit 元模型）</span></span>
<span class="line"><span>    ├── render.json                     # CAD 渲染载荷（仅 dxf，run/save 后原子发布）</span></span>
<span class="line"><span>    ├── issues.json                     # issue 列表（仅文件存储模式）</span></span>
<span class="line"><span>    ├── issues/{issueId}.png            # issue 截图（文件与 PG 模式均在此）</span></span>
<span class="line"><span>    ├── changes.json                    # 修改记录（仅文件存储模式）</span></span>
<span class="line"><span>    ├── overrides.json                  # 属性 override（仅文件存储模式）</span></span>
<span class="line"><span>    ├── edit-history.json               # services/ifc 持久化编辑历史</span></span>
<span class="line"><span>    ├── pending.json                    # script-run 回放簿记（内部）</span></span>
<span class="line"><span>    ├── script_staging.json             # 暂存脚本链（原子写，重启恢复）</span></span>
<span class="line"><span>    ├── bootstrap.ifc                   # 首次暂存脚本时保留的上传原件</span></span>
<span class="line"><span>    ├── current.map.json                # 当前 ScriptMap 发布信封</span></span>
<span class="line"><span>    ├── scripts/                        # 大版本脚本快照：v{n}.py + v{n}.map.json 全留</span></span>
<span class="line"><span>    ├── versions/                       # 大版本产物：v{n}.ifc|.dxf 只留最新</span></span>
<span class="line"><span>    └── ifc_cache/                      # diff/下载时按需重建的历史版本 + .map.json sidecar</span></span></code></pre></div><p>写入方分两组：uploads、model.json、XKT、metadata、projects、plans 和 issues/changes/overrides 由 Go server 与 converter 写；其余由 Python 服务直接读写，不经过 Go store。Go 和 Python 共享的是<strong>目录契约</strong>，不是同一个 store 实例。</p><p>跨语言共享目录只有一条硬约束：<strong>先写临时文件再 rename，禁止原地截断写</strong>。</p><h2 id="两种存储实现" tabindex="-1">两种存储实现 <a class="header-anchor" href="#两种存储实现" aria-label="Permalink to &quot;两种存储实现&quot;">​</a></h2><p>文件存储是默认实现，零依赖：所有状态落在数据目录里，JSON 文件加原子写。</p><p>PostgreSQL 可选：设置 <code>VIEWER_PG_DSN</code> 即切换。三张表由各自的 <code>pgstore.go</code> 在构造时自动建立。</p><p>两处不对称要知道：</p><ol><li><strong>模型注册表不进 PG</strong>。模型元数据和上传文件始终是文件存储，PG 只承接 issue、change、override 三个网关侧数据。</li><li><strong>Issue 截图不进 PG</strong>。PG 模式下 PNG 仍落盘，库里只存相对路径。</li></ol><p>这两点决定了备份要同时覆盖数据目录和 PG，缺一不可。</p><h2 id="第三方整合路径" tabindex="-1">第三方整合路径 <a class="header-anchor" href="#第三方整合路径" aria-label="Permalink to &quot;第三方整合路径&quot;">​</a></h2><p>按耦合从高到低三条路：</p><ol><li><p><strong>实现 Go store 接口</strong>，用自己的数据库承接网关侧状态。三个接口分别在 <code>issue.go</code>、<code>change.go</code>、<code>override.go</code>：</p><table tabindex="0"><thead><tr><th>接口</th><th>方法</th><th>职责</th></tr></thead><tbody><tr><td><code>issue.Store</code></td><td><code>List</code> / <code>Create</code> / <code>Update</code> / <code>Delete</code> / <code>DeleteModel</code> / <code>SaveScreenshot</code></td><td>issue 增删改查、按模型清理、截图落盘</td></tr><tr><td><code>change.Store</code></td><td><code>List</code> / <code>Append</code> / <code>DeleteModel</code></td><td>修改记录追加与按模型清理</td></tr><tr><td><code>override.Store</code></td><td><code>GetAll</code> / <code>Set</code> / <code>DeleteModel</code></td><td>属性 override 读写与按模型清理</td></tr></tbody></table><p>注意模型注册表 <code>store.Store</code> 是具体类型不是接口，替换它要改 server 内部装配。</p></li><li><p><strong>复用本仓 PG schema</strong>：把三个 <code>pgstore.go</code> 里的建表语句跑到自己的 PG 实例，设 <code>VIEWER_PG_DSN</code> 指向它即可。</p></li><li><p><strong>只做文件级对接</strong>：直接读写数据目录，耦合最低，适合只读消费 XKT、metadata 或旁路分析。写入方必须遵守上面的并发纪律。</p></li></ol><p><code>data/</code> 是运行时目录，不要手工修改。</p><h2 id="前端对接契约" tabindex="-1">前端对接契约 <a class="header-anchor" href="#前端对接契约" aria-label="Permalink to &quot;前端对接契约&quot;">​</a></h2><p>平台本体是 API，<code>web/</code> 只是一个可整体替换的参考实现。对接面是 Go 网关的 <code>/api/v1/*</code>（信封响应）和 <code>/v1/models/*</code>（静态直挂）。</p><h3 id="协议基线" tabindex="-1">协议基线 <a class="header-anchor" href="#协议基线" aria-label="Permalink to &quot;协议基线&quot;">​</a></h3><p>除静态文件端点外，所有响应统一 envelope，<code>code=0</code> 表示成功：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ok&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}}</span></span></code></pre></div><p>八个错误码的含义、鉴权豁免端点与 CORS 规则见 <a href="/SourceAEC/reference/rest-api">REST API</a>。</p><p>SSE 事件流：<code>GET /api/v1/chat/sessions/{cid}/events</code> 返回标准 SSE 帧，服务端维护编号缓冲，断线可以用 <code>Last-Event-ID</code> 重放最近 64 条。帧类型见<a href="/SourceAEC/reference/api-chat#sse-events">对话 API 的帧表</a>。</p><h3 id="编辑流程对接" tabindex="-1">编辑流程对接 <a class="header-anchor" href="#编辑流程对接" aria-label="Permalink to &quot;编辑流程对接&quot;">​</a></h3><p>一次典型修改只有四步：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BASE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">http://127.0.0.1:8090/api/v1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">MID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">m_0123456789abcdef</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. 暂存脚本（整脚本或 params 增量）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BASE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/models/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$MID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/script&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;script&quot;: &quot;...&quot;}&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. 沙箱试运行（预览，无版本；成功后 Go 侧排队重转 XKT）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BASE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/models/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$MID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/script/run&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. 保存大版本 v{n}</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BASE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/models/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$MID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/script/save&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;note&quot;: &quot;v1&quot;}&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 4. 轮询模型状态，converting 变 ready 说明新 XKT 可取</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BASE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/models&quot;</span></span></code></pre></div><p>配套端点还有 <code>script/undo|redo|discard</code>、<code>script/rollback</code>、<code>script/staging/diff</code>、<code>GET .../scripts</code>、<code>script/locate</code>，以及只读的 <code>edit/versions</code>、<code>edit/diff</code>。逐个端点的 body 与响应见 <a href="/SourceAEC/reference/edit-api">IFC 编辑 API</a>；给 AI agent 用的完整走查见 <a href="/SourceAEC/reference/ai">AI 接入</a>。</p><h3 id="显示对接" tabindex="-1">显示对接 <a class="header-anchor" href="#显示对接" aria-label="Permalink to &quot;显示对接&quot;">​</a></h3><table tabindex="0"><thead><tr><th>端点</th><th>说明</th></tr></thead><tbody><tr><td><code>GET /v1/models/{id}/model.xkt</code></td><td>XKT 几何数据，支持 Range</td></tr><tr><td><code>GET /v1/models/{id}/metadata.json</code></td><td>xeokit 元模型，schema 见<a href="/SourceAEC/reference/api-model#metadata-json-schema">模型与审查 API</a></td></tr><tr><td><code>GET /v1/models/{id}/render.json</code></td><td>DXF 渲染数据，仅 dxf 模型</td></tr></tbody></table><p>自研前端可以用任何渲染器。用 xeokit 时 <code>metadata.json</code> 可以直接作为 <code>XKTLoaderPlugin.load</code> 的输入，实体 id 就是 IFC GlobalId，和编辑 API 的 guid 天然对齐。</p>`,31)])])}const g=a(t,[["render",p]]);export{k as __pageData,g as default};
